	Changelog = {
		{ Date = "2026-09-27", Notes = "Seed created from the PRD. Nothing built yet." },
		{ Date = "2026-09-27", Notes = "PRD expanded (GTA 6 Deep Dive, Game Design Spec, Tech Spec tabs). Added car boost, Suspect Card/disguises, rain, Florida moments, radio, minimap. Neon Coast total 101h." },
		{ Date = "2026-09-28", Notes = "Step 1.1: NeonCoast.rbxl created by user. Folders: Workspace.City/Heists/Spawns/Vehicles, ReplicatedStorage.Shared.Config/Util + Remotes, ServerScriptService.Services, ServerStorage.VehicleTemplates/Tools, StarterPlayerScripts.Controllers. StreamingEnabled on, walk speed 18. Config.Vehicles added (12 land vehicles)." },
		{ Date = "2026-09-28", Notes = "Dev workflow: local files are the source; python http.server on 127.0.0.1:34999 + ServerStorage.Tools.DevSync pulls them into Studio (HttpService.HttpEnabled turned on for this). tools/manifest.py maps files to scripts." },
		{ Date = "2026-09-28", Notes = "Step 1.2: ServerStorage.Tools.CityGen builds the greybox (7 districts, Highway 1 loop, avenues + grid, ocean + prison moat terrain water, ~190 placeholder buildings with neon bands, heist/spawn/service markers, car pads, edge walls, golden-hour lighting). Buildings touching roads or markers are removed automatically." },
		{ Date = "2026-09-28", Notes = "Step 1.3: raycast car. CarBuilder (greybox cars from Config), VehicleService (spawn in front of player, one car per player, owner-only driving, network owner = driver, exit remote, idle despawn 10 min), DriveController (springs along ground normal, grip as per-second rate, handbrake drift, nitro, chase camera with wall check, F exit, R flip), VehicleVisuals (wheels for other cars). Tested: Palmetto 0-100 in ~3.2s, top 116/120; Vortex 194 straight with zero pull; drift slides ~42 studs/s and recovers in 0.3s; parked creep 0; enter/exit/flip OK. Studio test: number keys spawn cars (CoreGui blocks them for MCP input; use the remote)." },
		{ Date = "2026-09-28", Notes = "Step 1.4: DriveUI (speed gauge in MPH + nitro bar for everyone; phone: GAS/BRAKE pedals override throttle so the thumbstick only steers, NITRO, DRIFT, EXIT, FLIP when upside down; hides Roblox's jump button while driving). Studio preview: set LocalPlayer attribute PreviewTouch = true. Camera moved closer (13.5 + 5*speed). PHONE TEST PENDING (needs a private publish)." },
		{ Date = "2026-09-28", Notes = "Step 1.5: starter car waits on a free car pad for your side (robber pads face north, cop pads face south), space check against cars/buildings/players, cars in water (chassis y < 0.2 for 2s) or below -60 are removed with a 'Your car sank!' toast (NotifyController, server sends keys only)." },
		{ Date = "2026-09-28", Notes = "Step 1.6: VehicleGuard checks driven cars every 0.5s: teleport > 300 studs or speed > nitro top x 1.25 + 15 (2 samples) -> snap back + flag; 5 flags in 5 min -> car removed. Studio only logs unless Workspace attribute GuardEnforceInStudio = true. Tested: fake teleport and a 250 studs/s speed hack both caught. RULE: any future server-side car teleport must call VehicleGuard.Allow(car) first." },
		{ Date = "2026-09-28", Notes = "Steps 2.1/2.2/2.8: TeamService + TeamUI picker, HeistService (rotation of 4 open types, bank event every 15 min, server-timed hold-to-rob, bags, alarm after 10s head start), EconomyService (Cash/Carried attributes + leaderstats), HideoutService (bank when unspotted, clears heat), HUDController (cash/bag/heat stars/stamps), HeistClient (site signs, prompt visibility), FeedController (Coast Feed toasts). Full loop tested: rob Glow Mart -> bag $1,200 -> bank -> CLEAN GETAWAY." },
		{ Date = "2026-09-28", Notes = "DIRECTION CHANGE (user approved): open world, GTA-style. Roles: Civilian (default, free roam, can commit crimes -> Wanted via heat), Cop (job), Prisoner. 'Robber' renamed to 'Civilian' everywhere. 3 civilian spawns (downtown, beach, Palm Hills) + hideout, 14 civilian pads, 5 cop pads. Planned activities: street races, stunt jumps, drift zone, jet ski course, taxi/delivery job, car meet lot, phone missions (+~27h)." },
		{ Date = "2026-09-28", Notes = "Review fixes (11 bugs): VehicleGuard rewritten (pcall per car, reference = last good sample, tracks every client-owned car, rise/spin checks, snap back via server ownership, removal via VehicleService.Despawn + CarRemoved); spawn requests rate-limited, refused while Wanted, ground-only raycast, no car for departed players, weak tables; Drive prompt only on your own empty car; touch pedals track each finger's InputObject; jumping disabled while seated (no more jump-button hiding); wheels use Motor6D.Transform; HUD CAR button." },
		{ Date = "2026-09-28", Notes = "Steps 2.4/2.5/2.7: HeatService (250-stud sight with walls blocking, hollow after 8s, escape after 30+10*heat s, hot zones, 4+ star pings, bounty 500/star + 25% bag), ArrestService (taser T, spikes G with 2 charges, cuff prompts only on wanted players, AI/cop arrests, patrol pay $80/min), PrisonService (45+15*heat s timer, vent breakout -> wanted 2 stars; breakout only counts after being seen on the island), LawClient (cop markers, search circles, stamps, mugshot headlines), RateLimit, DebugService (Studio: NCDebug bindable)." },
		{ Date = "2026-09-28", Notes = "Step 2.9: CarPhysics shared module (client driver + server AI), RoadGraph (nodes/edges from road parts, A*, published as JSON), AIPoliceService (spawns when < 2 player cops, follows roads, direct pursuit near/in sight, capped at 95% of target speed, parks a car length away, arrests after ~3s stopped). FIX: roads/walls longer than 2048 studs were silently truncated (gaps in the highway) -> CityGen now builds long roads/walls from pieces." },
		{ Date = "2026-09-28", Notes = "Step 2.11: Suspect Card (SuspectOutfit / SuspectCar attributes noted by cameras and cop sightings, shown on cop markers), DisguiseService (hideout wardrobe hats/masks from parts, -1 star when unseen; Spray & Go $500 respray, -1 star, 30s cooldown), WardrobeUI, car swap allowed while hollow. Tested: disguise 2->1 star, respray 2->1 star." },
		{ Date = "2026-09-28", Notes = "Step 2.10: CarBoostService (3 hot cars on roadsides, 4s server-timed lock pick, +1 heat, 40% GPS tracker ping after 20s, Chop Shop delivery -> value into bag). Step 2.6: RobberToolsService smoke (6 invisible sight-blocking clouds + particles, 1 charge / 30s; CarPhysics/camera/wheel rays ignore Workspace.Smoke). Step 4.1 (pulled forward): DataService (session lock, retries, autosave 60s, BindToClose, Studio memory fallback; saves cash, look, stats)." },
		{ Date = "2026-09-28", Notes = "Phase 6 activities: RaceService (3 street races, countdown, checkpoints, par bonus, PBs, board), StuntService (8 stunt jumps, slow-mo), DriftService (Lighthouse Key drift zone, combo scoring, paid per chain), JobService (taxi shifts with roadside passengers, distance pay + speed tip). ActivityClient UI." },
		{ Date = "2026-09-28", Notes = "Phase 3 art: ArtKit + ArtGen (styled buildings per district, 375 street lights, centre lines), generated meshes (palm, flamingo statue, gator, lighthouse, Ferris wheel, yacht, cypress, tropical bush), art modules HeistFronts / Beach / PalmHillsDowntown (parallel agents, reviewed with screenshots; DocksMarina + GladesPrison pending). WorldService: 12-min day/night, storms (wet grip x0.75), night heists +25%. SkyClient rain/lightning/night windows." },
		{ Date = "2026-09-28", Notes = "Steps 4.2/4.3/4.8: GarageService (owned cars saved, paint $500 / rims $1,500 / underglow $3,000 once per car), phone (Garage, AutoNeon dealer, GPS with road routes + light pillar, Jobs, Shop; design-size UI scaled to any screen), MapService (places, open heists, map shapes), MinimapClient (ViewportFrame top-down map, GPS line, rim-pinned blips, wanted flash)." },
		{ Date = "2026-09-28", Notes = "Step 3.4: TrafficClient (client-side ambient traffic on the RoadGraph, lanes by road width, slows for corners and cars ahead, stops for players, knocked flying when rammed; collision groups Vehicles/Traffic). Step 3.2: mesh bodies for all 12 cars (generate_mesh segmented body/wheels/windows/lights/bumpers, BodyPrep tool, IDs in tools/CAR_BODIES.md), visual wheels moved into the arches; 3 textured traffic models." },
		{ Date = "2026-09-28", Notes = "Steps 4.4-4.7: TutorialService/Client (4 steps, SHOW ME routes the GPS, $500 bonus), ShopService (5 passes + 5 cash packs, idempotent ProcessReceipt saved with the cash, live prices, VIP chat tag, pass paints/glows; IDs = 0 until the Creator Hub items exist), DailyService (login streak $1k..$7k, streak paint), Telemetry (economy, onboarding funnel, custom events)." },
		{ Date = "2026-09-28", Notes = "Step 3.6: SoundClient + Config.Sounds (all ProSoundEffects / APM / Roblox Resources): engines, sirens (H toggles for cops), horn (H), skids, nitro, doors, splash, alarms, rain/thunder, surf/gulls, city hum, UI, 3-station radio (V). LESSON: never start Play while generate_mesh jobs run (they fail)." },
		{ Date = "2026-09-28", Notes = "Progression (ranks 1-20 per side, unlocks, 3 daily challenges, GOALS app), boats (jet ski rental, Marlin, Harbor Patrol; CarPhysics boat mode; marina/beach boat pads; Surf Sprint boat race), crews (CrewService, CREW app, +20% crew / +10% friend bonus, passenger seat), Florida moments (EventService: gator, beach treasure, UFO), phone missions (5), pedestrians (PedClient), SETTINGS app (volumes, Performance mode), multi-step heists (bank fuse box, yacht alarm panel). All 5 art modules integrated (8,169 art parts). Spawns face their pads." },
		{ Date = "2026-09-28", Notes = "Code review round 2 (3 reviewers, ~31 findings fixed): passenger exploits (drift/stunt pay, ride from prison), Ride prompt server-enabled, boat rays from above water, AI ignores boats, wheel radius, DataService.OnLoaded (no more 15 s polling), honest save result, verified pass purchases, crew invite race, clock-skew day checks, Remotes.OnClient (non-blocking), minimap culling, traffic non-colliding, UI overlaps on phones, stamp queue." },
		{ Date = "2026-09-28", Notes = "Owner playtest feedback batch 1 (7 features, built + reviewed + fixed by a workflow): car hits knock people down (no damage) and car-on-car hits cut speed 45-60%; F / GET IN button enters your car or a stolen hot car, 'get out first' hint; objective banner + auto GPS for every crime step, bank shows 'rank 3' before you try, cops get a head start delay after ATM/store robberies, 5-star HUD; toasts on the left with category icons; wardrobe room with a camera on your character; HOMES (3 to buy, saved, spawn + garage showing your cars; data.home, data.lastCar); physical dealerships (AutoNeon Motors downtown, Marina Boat Sales), buying only in person; 4 premium cars ($120k-$450k) + 2 boats; automatic seat fitting." },
		{ Date = "2026-09-28", Notes = "Seats: head at side-window height, seats 15.5% of body width from centre (hands inside the doors), dark tinted glass on all closed cars; hand-tuned Gatorback (was driving from the bed), Solana GT (head through roof), Flamingo, Sandpiper. Mesh bodies for Silver Egret, Albatross GT, Riptide R, Storm Petrel, Swordfish, Moonstone Yacht (tools/CAR_BODIES.md)." },
		{ Date = "2026-09-28", Notes = "Owner decisions: knockout combat (fists + stun blaster, KOs drop 25% of the bag, no deaths; cops keep tasers) and art direction 'realistic + neon'. Look 2.0: facade window textures (own images, tools/textures.py, Config.Textures), storefronts, sidewalk slabs, realistic day lighting (warm sun, clouds), Restyle tool (materials, clay-tile houses, corrugated warehouses, 190 street-front infill buildings, 97 block buildings + 29 car parks with parked cars + 24 pocket parks, 62 crosswalked crossings with 206 cycling traffic signals, ~1,000 hydrants/bins/news boxes/benches, yellow centre lines, Glades cypress/swamp pools/sawgrass), facade night lights. Owner must set Lighting.Technology = Future in Studio (not scriptable)." },
		{ Date = "2026-09-28", Notes = "Knockout combat (CombatService/CombatClient/Config.Combat): Fists for every civilian, Stun Blaster $2,500 at the Zap Shack (-250,-330), daze meter -> 5 s KO (no health loss, no deaths), 25% of the bag drops as a grabbable duffel (+1 star to grab; cops return it for up to $100), max 2 stars from fighting and fight stars pay no bounty/XP, safe zones (spawns, shops, homes, Hideout, Police HQ, Car Meet), spawn protection, passive mode (PHONE > SETTINGS; refused while wanted/carrying/fighting), feuds so self-defence isn't punished, bailing out (reset) counts as a KO. Punching pedestrians knocks them over (local). Downed cops can't taser/cuff." },
		{ Date = "2026-09-28", Notes = "Homes: 6 total, cheapest first - Rustwater Loft $25k (2-car), Palm Hills Bungalow $60k, Palm Hills Ranch $110k (3), Solana Heights Penthouse $180k (4), Marina Row Villa $400k (6), Flamingo Beach Mansion $1.2M (8); styles Loft/Ranch/Mansion. Review of the lead's own changes (12 fixes): signal poles clear of street lights/buildings, minimap shows the ~290 Restyle buildings + Marina paving, night glow only on faces toward the camera, upright exit from reclined seats, car spawns avoid hydrants/bins/benches, Glades trees off stunt corridors, phone text fits." },
		{ Date = "2026-09-28", Notes = "Pre-playtest audit (8 subsystem auditors + skeptics): 48 confirmed findings, all fixed and re-verified in 6 file-disjoint groups. Highlights: tasered/knocked players can't escape through E prompts; arrests mid-fight don't count as KOs; arrested car thieves lose the hot car; breakout and car-boost stars pay no bounty (NoBountyStars); AI police head start 15/12/8/4/4 s; pass and cop-rank cars show in GARAGE; boats can't be styled; anti-farm checks on car-meet likes, drift speed, missions, Florida moments and stunts (measured movement); traffic obeys the signals (Util.Signals); pedestrians stay on sidewalks and out of water; race leaderboards on the start pads; jail time kept across servers (data.jailUntil). Studio car test keys now need Left Alt (1/2 are the fists/blaster). All scripts compile (loadstring check)." },
		{ Date = "2026-09-29", Notes = "Owner playtest #2: 'I don't see how you can steal a car on the street' + 'make sure everything was changed'. Built CarjackService (JACK slow/stopped traffic cars with F or the pink JACK button, driver flees, same model+colour; BREAK IN car-park cars with alarm chance; street car types StreetHatch/Sedan/Pickup from the traffic meshes; sell at the Chop Shop $250-450; +1 star only when not wanted). Phone HOW TO PLAY guide. 22-item checklist audit of the owner's feedback: gaps closed (car-into-car keeps rolling, GetOutFirst everywhere, EXIT (F), passenger EXIT, wardrobe at home, Studio 'saving is off' notice, seat overrides in config). Police head start 20 s at 1 star. Street cars: wheel rays at body corners (hatch rolled), sedan/pickup drivers in front seats." },
		{ Date = "2026-09-29", Notes = "Idea panel (6 lenses + judge) produced a 15-item roadmap. Batch 1 built: Road to the Coast goal chains (tutorial car->rob->bank->phone, 12 civ + 5 cop goals with SHOW ME/EARN), invite/join friends + co-play bonus + Squad paint, chase readability (LOSING THEM meter, cop blips + edge arrows, spotted beep; radar On), right-moment pass offers, honest shop text (Hypercar not 'fastest'; cash packs can't skip locks), bag 22k, heist-locked supercars (Riptide 3, Storm Petrel 6, Moonstone 4 big heists)." },
		{ Date = "2026-10-02", Notes = "Owner playtest #3 (10 points) + 'make it feel like the big console crime games'. FIXED: never stuck in a car (exit from any seat with F / E / B / EXIT; driving starts when the whole car has loaded; raw key fallback), rob prompts hidden while seated (PromptGate), speed readout no longer covers the radio (car cluster bottom-right with a radio row and RADIO OFF), drifting that holds and scores + on-screen how-to (DRIFT ZONE banner, DRIFT tag, skid marks), race route chevrons + minimap line + turn cues, car tuning (PHONE > GARAGE > TUNE: engine / turbo / brakes / tyres / nitro stages, 5 exhaust sounds, AUTO TUNE). LOOK 3.0 (ServerStorage.Tools.Look3): brick / glass / stucco palette by district, neon only at night (tags NightNeon / NightLamp / NightShop), kerbs, lane dashes, parking bays instead of pink pads, 572 shop signs, ~1,300 palms, parked cars, billboards, yards, spawn plazas; Lighting style Realistic; 14-minute day in three acts starting at golden hour; runtime places (dealerships, homes, car meet, depot) restyled. Tooling: Studio's MCP Luau is sandboxed now (no require / remotes / HTTP): code sync is tools/syncpack.py + syncpack_apply.lua, edit-time tools run through syncpack_run.lua, tests use the NCCmd / NCClient attribute hooks." },
		{ Date = "2026-10-06", Notes = "Feel pass from research on the genre leaders (docs/FEEL_PLAN.md). HUD 3.0 (Util.Theme: flat street look + zone map): minimap bottom-left, cash / stars / rank top-right, PHONE and CAR tiles, toasts above the minimap, cinematic stamps, help text with key caps, title screen with a drifting city camera, realistic phone. GUNS (owner request; owner must update the maturity questionnaire): Coast Arms sells Pistol $2,500, SMG $9,000, Shotgun $16,000, Rifle $32,000 (rank 5), body armor $1,500; generated gun meshes (tools/GUN_MODELS.md); magazines + reload; health = 100 - daze with armor; knockouts not deaths; money from wallets (players and pedestrians), dropped bags and bounties on wanted players; cops get a service pistol that only works on 2+ star suspects; gunfire brings police. MOVEMENT: realistic walk / run sets (Config.Animations; mixed sets for pedestrians by district), sprint + stamina, lean, footsteps by surface, landings, over-the-shoulder camera with a request stack (LocomotionClient). POSES + RAGDOLL: PoseClient (hands up, cower, aim, low ready, flinch, driver hands, phone), Shared.Util.Ragdoll + RagdollService (knockdowns go limp for everyone and get up unhurt), hands up while being cuffed. CARS: body lean on a BodyJoint, head / brake / reverse lights, acted get-in (walk to the door), driver pose, NPC driver stumbles out when jacked, street furniture you plow through (PropService / PropClient, 1,712 props). CITY: area names, sound beds, planes / helicopter / ships / birds, neon lighting up block by block at dusk (AmbienceClient). Lesson: Luau allows 200 locals per function; keep every file's top level under 150 (constants in K, GUI refs in ui). Scripted Studio tests pass (shop, fire / reload, knockdown, car body joint, poses, props); visual pass pending (screen was locked)." },
		{ Date = "2026-10-06", Notes = "Visual pass (on screen, in play). Fixed: chase camera higher and further back (13.5 studs, 18 degrees: the road shows over the roof), aim camera further out and to the side (crosshair clear of the head), GET IN / JACK button in the flat HUD style, district name card readable, help strip never overlaps the minimap, shotgun mesh regenerated (the first was bent; ask the generator for 'lying perfectly level, side profile'). Called-in car that would not drive (seen once in five tries, cause not found): DriveController now has a safety net, at the wheel of a whole car and not driving means start, checked 4 times a second (forced the fault: driving back in 0.2 s). DUSK: the sun is on the horizon at 18:00 and the lamps came on at 19:00, so a new player's second and third minutes were near-black; sunset is brighter, a new DUSK look (pink magic hour) follows it, and IsNight (lamps, neon, lit windows) starts at 18:24. Tested by script: wallet from a shot pedestrian pays into the bag and raises heat; two stars brought patrols and an arrest; guns and cash kept after the arrest, bag lost." },
		{ Date = "2026-10-06", Notes = "Pre-playtest bug sweep (13 readers + skeptics over everything built since the last audit, then 13 file-disjoint fixers each reviewed from its diff; plus a scoped undefined-name check over all 118 files: clean). FIXED AND TESTED IN PLAY: a store closing mid-hold no longer cancels a robbery in progress; Reset Character with police within reach counts as giving up (cuffed, bag lost: ArrestService.GaveUp); LAUNCH a boat keeps your car (the boat waits at its pad until you sit in it); GARAGE > DELIVER from a seat steps you out and delivers; E / F in the dressing room no longer gets into your car; pedestrians fall when a car really reaches them; traffic appears out of sight and steers round an empty parked car; taxi / courier rings count where they are drawn (32 studs), no ghost shift, a shift or mission ends when you join the police; P on the title screen no longer opens the phone; second F / E after getting out no longer walks you back in. FIXED, NOT YET SEEN IN PLAY: passengers can't jump out through the roof, gamepad B behind the Roblox menu, house buy card with a gun out frees the mouse, no punch on dressing-room clicks, aim walk speed 12 (above the cuff threshold), stun / knock-out timers cleared on arrest, gun-out FOV, prison windows after the first night, taser-in-car message, own Like bubble at the car meet, D-pad down opens the phone. LOOK: indoor store lights at 30% (rooms were a white haze at night under Realistic lighting); the font has no cross or round-arrow glyphs (plain X < > now). LEFT: gamepad horn button; two empty cars in one lane (traffic sees the second late); two-player and touch tests." },
		{ Date = "2026-10-06", Notes = "Owner's numbers for pedestrians: wallets pay $50-100 (was $15-90), cap stays $900 per 10 minutes, and the police only start coming after the SECOND pedestrian you knock over (Combat.Ped.FreeVictims = 1, VictimMemory 180 s; Combat.Heat.PedVictim = 1). How: PedClient reports each of its own knock-downs (remote PedDown; the server takes only the count, and only within 3 s of a swing or shot it accepted; a wallet nobody reported counts its owner, so a tampered client gains nothing), CombatService.PedVictim keeps the count and puts the first star on at the second one; until then a shot the street hears and the wallet carry no star (police who hear the shot themselves, or a shot that hits a player, still count at once). The second one's own wallet adds no star; from the third on gunfire and wallets count as before (cap 3 with a gun, 2 with fists). The count starts again 180 s after the last one or when the stars are gone. Tested in play: 1st 0 stars + $51, 2nd 1 star + $91, 3rd 2 then 3 stars + $77." },
		{ Date = "2026-10-06", Notes = "Owner playtest #4 (4 points). (1) 'F does not exit my car all the time': the server moved you out beside the door, but your own device stood the body up in the seat a fifth of a second later and it came out through the ROOF and stayed on the car (seen on every parked exit once logged frame by frame). Now the server also tells the device the spot (remote CarExitSpot) and DriveController stands the body there the moment the seat lets go (0 frames on the car), with a 1 s server safety net. Also: a second F within 1.2 s of getting out does nothing (was 0.6: you walked back in), for 5 s the car you left is outranked by any car you could take, and the step-out spot is measured from the car's middle (driver's side blocked used to put you inside the car). (2) 'It takes a long time to kill someone': a bullet that TOUCHED a pedestrian stopped on the torso half a stud short of the hit test and did not count (a Humanoid keeps CanCollide on, so CanQuery = false means nothing); only near misses knocked them over. Shot rays now pass through Workspace.Peds, the crosshair picks the walker under it (PedClient.Under: no more parallax miss in open streets), a walker in the camera's plain sight is hit even when the bullet's own line from the head meets a post, a walker can be hit again 2.5 s after falling (was 5), a click up to 0.15 s early is kept, spawn protection 8 s (was 20). Before: 3 dead-centre shots, 0 knock-downs; after: first shot. Player damage numbers were already at arcade targets and are unchanged. (3) Waves: Terrain.WaterWaveSize 1 / speed 14 (the most the engine draws) and boats ride a swell in CarPhysics (two crossing waves off the server clock; jet ski heaves 0.75 studs at rest, never airborne at 110); boat pads invisible. (4) Jet ski regenerated (tools/CAR_BODIES.md): long low hull, saddle, handlebars." },
		{ Date = "2026-10-14", Notes = "Taxi / courier shifts route the GPS to the pick-up and the drop-off (minimap line, star, road dashes). Then the owner asked for the game to feel more like the big open-world crime series. Research (genre look, HUD conventions, IP rules, Roblox market, fonts) said: keep our own name and mark (a copied title, a sequel number or a numeral-style logo is the riskiest thing a Roblox game can do, and copycat names get few players), borrow the mood and the genre conventions in our own words. Done: big moments (HUDController stamps) are now headline banners: huge slanted Bangers title (Theme.Font.Big) with a thick black outline and drop shadow that slams in on a dark band across the screen, plus an optional reward line ('+$500   +50 XP', cash green, XP gold) that pops in a beat later and the Passed sting (APM 80s synth-pop, Sounds.Passed); used by MISSION PASSED, ROBBERY / HEIST COMPLETE and CAR DELIVERED (new titles, kicker = the place), FARE PAID / DELIVERED and CLEAN GETAWAY (banking). Every XP gain floats a gold '+15 XP' left of the RANK (ProgressClient). New wanted stars slam in. Title screen: a new NEON / COAST logo built from UI (Montserrat Heavy Italic, Theme.Sunset fill, Theme.Ink outline and shadow, striped synthwave sun; TeamUI LOGO_WORDS). Stamp zone 164 / 120 px tall. Studio test hook NCClient takes {c3} colours and '$nil'." },
		{ Date = "2026-10-14", Notes = "Owner named the game THEFT MIAMI COAST (logo: three stacked lines over the striped sun, TeamUI LOGO_WORDS; the city is still Port Solana; never add Grand / Auto / 6, keep the big series' name out of tags). THE BIG SCORE (BigScoreService + BigScoreClient, Config.Heists.BigScore): a 2-4 player crew heist started from the phone's CREW app: hack the armored van at the Ironclad depot (the port, by the Hideout), drive it to the Solana Gold Reserve (Palm Hills, north of downtown), two crew hold the gate consoles at once, drill the vault (alarm, 2 stars) while defending it, carry up to 12 gold bars ($8,000 each) to the van, deliver it to the Hideout: pot split evenly, banked, 160 XP, counts as a big heist. Both sites are built from a design layout and moved as one piece (Design + DepotMove / ReserveMove: the first lots were home plots). Armored van = the Riot Truck body with dark trim (CarBodies.ArmoredVan). Coastal Bank / Sea Dream now pay a cut to every Civilian crewmate within 80 studs (pot +50% per helper, split evenly). Sound pack (APM / ProSoundEffects): wanted star hit, lost-the-cops sting, cash register, police radio chatter while wanted (generic dispatcher clips only), heist music, drill, vault alarm, gold clink, gate, failed sting on red stamps. Tourable apartment towers (ApartmentService, Config.Apartments): 8 downtown towers get a lit lobby entrance and a rooftop penthouse with the real city view (living room, kitchen, bedroom, pool terrace, glass railings), open to all, elevator back down; GPS lists them. Home tours (HousingService / HouseClient): TOUR on any home's buy card walks you through a show version with a FOR SALE stand. Big-series HUD feel: cash in the headline font with a black outline, bigger outlined stars, car names in script, mission intros with letterbox bars and a script title (HUDController.Intro), weapon wheel on hold Tab / D-pad left (WeaponWheel)." },
		{ Date = "2026-10-14", Notes = "Owner: fix anything else. Play test of the Big Score with real key holds (hack 5 s, both consoles, drill, grab) passed; it found E at the van's back doors taking Ride instead of Load (Board prompts now hidden while carrying), vault lamps too strong (0.4), and the chase camera too low behind the tall van. Sweep (4 areas, find then verify-and-fix): depot cameras no longer count as police eyes (they could see the Hideout pad and block banking); crewmates get stars when they take the van's wheel or grab gold (no untouchable 0-star carrier); runs fail when a crew drops below 2 before the gate; knocked-out members don't count; one player can't finish both consoles; the gate won't shut on someone; Big Score cooldowns are saved; phone BIG SCORE row matches the server's rules; GPS route comes back after prison; the bystander alarm stops when a run ends; no rain inside penthouse rooms (InApartment); penthouse seats exit to clear spots (ExitAt); CAR on a tour or in a penthouse says no room; ApartmentWanted toast; chase camera rises and backs off for tall bodies (Armored Van, Riot Truck); weapon wheel opaque over the HUD; intro owns DisplayOrder 4 (CombatHUD 3, Locomotion / ImpactFx 2) and the GPS readout gives way to it; no lost-the-cops sting over a payout; Music volume slider label." },
		{ Date = "2026-10-15", Notes = "Look 4.0 (owner: make it look better, more like the big series; take your time). Toured the city in play at noon, sunset and night first: night already read well, daytime was flat and toy-like. (1) Lighting (WorldService): new DAY / GOLDEN / SUNSET looks: warm sun, crisp dark-grey shadows (low EnvDiffuse + warm bright OutdoorAmbient stop the deep blue sky turning shaded asphalt navy), +saturation and contrast, blue distance haze; GeographicLatitude 41 so the midday sun rides lower (72 deg) and casts long shadows; the day's high-noon stretch (9:30-14:00) now passes fastest. (2) Sea: Terrain water a deep Gulf turquoise (18,150,170, transparency 0.45; CityGen). (3) Cars: glossy paint (Reflectance on every car body: CarBuilder, traffic, parked); traffic paint list is now real street colours; ten re-textured street-paint bodies (ReplicatedStorage.TrafficVariants: white / silver / black / navy sedans, white / red / grey pickups, silver / black / red hatchbacks; attributes Kind + Paint) join traffic, and 209 of 316 parked cars were swapped to them (tools/PROPS.md). (4) Busier streets: traffic 22 cars (was 14), pedestrians 16 (was 12); performance mode unchanged. (5) City dressing at every server start (CityDressingService runs ServerStorage.Tools.Look4 after the lots it keeps clear of): 36 billboards (20 rooftop on steel legs with lamps that light them at night, 16 tall pole boards by the highway and avenues) showing 12 original parody ads made in tools/make_look4_art.py (Sunset Soda, Flamingo Burger, Coast FM 104.2, Sal Breeze attorney, Solana Smiles, Palm Hills Realty, Gator Glades tours, AutoNeon Motors, Zap Shack, Club Nova roller disco, Coastal Bank, Marina Row Yacht Club; ids in Config.Textures), about 900 road-wear decals (cracks, oil, patches, skids, manholes, storm drains), and 219 tall royal palms (generated mesh ServerStorage.Props.TallPalm) lining the beach road, Solana Ave, Marina Row, Palm Blvd and the causeway; 1790 parts, 0.3 s. (6) Yellow centre lines a worn road yellow. (7) Kid-safety: LUCKY LOTTO shop signs are now LUCKY LEMONADE; Look3's lotto and gun-shop text ads replaced in the tool." },
		{ Date = "2026-10-26", Notes = "Owner playtest on THEFT MIAMI COAST (13 points; the Oct 25 Studio save is now the project base, the older Neon Coast line is kept on branch reference/older-neon-coast-line). UI: one PLAY on the title screen (free roam only), police is an optional job in PHONE > JOBS (GO ON / OFF DUTY); paint and rims are bought once per car and stay owned (data.custom[id].paints / .rims, swatch captions, TAP AGAIN TO BUY); the SHOP lists all 5 passes and 5 cash packs (free in Studio and for the owner, RequestShopFree); a tap outside the phone closes it; Road to the Coast goal 4 'buy your first gun at Coast Arms' ($1,000). Guns: RightGripAttachment / RightGrip reset to the standard turn on every avatar (CombatService normalizeGrip). Phone HUD: goal strip and banner end short of Status, AIM moves off the subtitles." },
		{ Date = "2026-10-26", Notes = "Cars (owner playtest): jet ski from the dock (own boat's Drive bubble no longer held back; boat bubbles reach 60; launching on foot near the pad seats you). Empty nitro latched off until released, one fading whoosh and a click. Getting out: seat found from the weld when SeatPart is nil, every joint and leftover SeatWeld removed, sweep each second and on CharacterRemoving, riders put out before a car goes, client retry at 0.7 s, a 'still held' report in Output and the live /console. Likely cause (not confirmed in play): CharacterBreakJointsOnDeath is off, so a reset in a seat left a weld the old exit could destroy instead of yours. Seats: per-rider fit (CarBuilder.FitRider; hand-placed seats measured against the body top), riders lean with the body, Riot Truck / Armored Van driver up in the cab, boat crews on deck (estimated), CarBuilder.Showroom. Taxi fares ride visibly (SeatNPC) and walk off. Crewmates and Roblox friends ride together (CrewService.MayRide, RIDE button, RequestRide; boats: level wall check over the dock rails)." },
		{ Date = "2026-10-26", Notes = "Houses (owner playtest): six one-of-a-kind builds (HouseBuilder kit + Services.Houses.<Style>): Rustwater Loft, Palm Hills Bungalow, Palm Hills Ranch, Solana Heights Penthouse, two-storey Marina Row Villa, three-level Flamingo Beach Mansion with an 8-car showroom; terrain-water pools in the private copies; the old look is the fallback if a build fails. Owners spawn inside their home (citizens, no heat; first join waits at the door until PLAY), wanted players are put out, the home driveway isn't used while wanted. Review fixes: goal strip measured in the HUD's own width (notched phones), steady STYLE grid between the two taps, a goal that moves in the list keeps its progress, Studio free cash packs only for the owner while saves are on, dead riders stay seated until removed; houses: PLAY pressed while the door area loads still takes you in, arriving to meet a friend (MeetPending, FriendsService) skips the home spawn, no copy is built for a player who already left, Drive this is refused while wanted, the cinema rows step out into the aisle. Manifest: 133 scripts." },
	},
}
